CREATE OR REPLACE FUNCTION public.validate_academy_lesson_progress() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.academy_lessons l WHERE l.id=NEW.lesson_id AND l.course_id=NEW.course_id) THEN RAISE EXCEPTION 'Lesson must belong to the selected course'; END IF; IF NOT public.is_enrolled_in_course(NEW.user_id,NEW.course_id) AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Active course enrolment is required'; END IF; RETURN NEW; END; $$; REVOKE ALL ON FUNCTION public.validate_academy_lesson_progress() FROM PUBLIC; CREATE TRIGGER validate_academy_lesson_progress BEFORE INSERT OR UPDATE ON public.academy_lesson_progress FOR EACH ROW EXECUTE FUNCTION public.validate_academy_lesson_progress();